package com.company.skillplatform.workflow.application;
import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import com.company.skillplatform.audit.application.AuditService;import com.company.skillplatform.dependency.application.DependencyService;import com.company.skillplatform.dependency.infrastructure.repository.SkillVersionDependencyRepository;import com.company.skillplatform.skill.application.SkillService;import com.company.skillplatform.skill.infrastructure.entity.SkillEntity;import com.company.skillplatform.skill.infrastructure.repository.SkillRepository;import com.company.skillplatform.user.domain.IdentityProviderType;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import com.company.skillplatform.user.infrastructure.repository.IamUserRepository;import com.company.skillplatform.version.domain.*;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.workflow.domain.PublicationPort;import com.company.skillplatform.workflow.domain.ReviewStatus;import com.company.skillplatform.workflow.infrastructure.entity.*;import com.company.skillplatform.workflow.infrastructure.repository.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import org.springframework.test.util.ReflectionTestUtils;
class WorkflowServiceTest{SkillReviewRepository reviews=mock(SkillReviewRepository.class);SkillStatusHistoryRepository histories=mock(SkillStatusHistoryRepository.class);ArtifactBuildTaskRepository tasks=mock(ArtifactBuildTaskRepository.class);SkillRepository skills=mock(SkillRepository.class);SkillVersionDependencyRepository dependencies=mock(SkillVersionDependencyRepository.class);SkillService skillService=mock(SkillService.class);DependencyService resolver=mock(DependencyService.class);IamUserRepository users=mock(IamUserRepository.class);PublicationPort publication=mock(PublicationPort.class);AuditService audit=mock(AuditService.class);WorkflowService service;IamUserEntity user;SkillEntity skill;SkillVersionEntity version;AtomicReference<SkillReviewEntity> reviewRef=new AtomicReference<>();AtomicReference<ArtifactBuildTaskEntity> taskRef=new AtomicReference<>();
 @BeforeEach void setup(){user=new IamUserEntity(IdentityProviderType.MOCK,"u","u","h","U",null);ReflectionTestUtils.setField(user,"id",1L);skill=new SkillEntity("root","Root","d",null,user);ReflectionTestUtils.setField(skill,"id",2L);version=new SkillVersionEntity(skill,null,ChangeType.INITIAL,user);ReflectionTestUtils.setField(version,"id",3L);service=new WorkflowService(reviews,histories,tasks,skills,dependencies,skillService,resolver,new SemanticVersionPolicy(),users,publication,audit,Clock.fixed(Instant.parse("2026-09-02T00:00:00Z"),ZoneOffset.UTC));when(users.findById(1L)).thenReturn(Optional.of(user));when(skillService.version(3L)).thenReturn(version);when(skills.findBySkillKeyForUpdate("root")).thenReturn(Optional.of(skill));when(reviews.save(any())).thenAnswer(i->{SkillReviewEntity r=i.getArgument(0);ReflectionTestUtils.setField(r,"id",4L);reviewRef.set(r);return r;});when(tasks.save(any())).thenAnswer(i->{ArtifactBuildTaskEntity t=i.getArgument(0);ReflectionTestUtils.setField(t,"id",5L);taskRef.set(t);return t;});}
 @Test void submitsApprovesPublishesDeprecatesAndOfflines(){var submitted=service.submit(3L,0,"review",1L,"r");assertThat(submitted.candidateVersion()).isEqualTo("1.0.0");when(reviews.findById(4L)).thenAnswer(i->Optional.of(reviewRef.get()));when(reviews.findByStatusOrderBySubmittedAtAsc(ReviewStatus.PENDING)).thenAnswer(i->List.of(reviewRef.get()));assertThat(service.reviews()).hasSize(1);assertThat(service.review(4L).versionId()).isEqualTo(3L);service.approve(4L,"ok",1L,"r");assertThat(service.review(4L).reviewerName()).isEqualTo("U");var task=service.publish(3L,"key",1L,"r");assertThat(task.status()).isEqualTo("SUCCEEDED");when(tasks.findById(5L)).thenAnswer(i->Optional.of(taskRef.get()));when(tasks.findByVersionIdOrderByTimeCreatedDesc(eq(3L),any())).thenReturn(new org.springframework.data.domain.PageImpl<>(List.of(taskRef.get())));assertThat(service.task(5L).versionId()).isEqualTo(3L);assertThat(service.tasks(3L,org.springframework.data.domain.Pageable.unpaged())).hasSize(1);service.deprecate(3L,null,1L,"r");when(dependencies.findByDependencySkillId(2L)).thenReturn(List.of());assertThat(service.impact(3L).blocked()).isFalse();service.offline(3L,false,"retired",1L,"r");assertThat(version.getLifecycleStatus()).isEqualTo(LifecycleStatus.OFFLINE);verify(publication).build(3L);}
 @Test void rejectsAndWithdrawsReviewsAndReturnsIdempotentTask(){SkillVersionEntity rejected=new SkillVersionEntity(skill,null,ChangeType.INITIAL,user);ReflectionTestUtils.setField(rejected,"id",8L);rejected.submit("1.0.0",user);SkillReviewEntity review=new SkillReviewEntity(rejected,1,user,"x",Instant.EPOCH);ReflectionTestUtils.setField(review,"id",9L);when(reviews.findById(9L)).thenReturn(Optional.of(review));service.reject(9L,"no",1L,"r");assertThat(rejected.getLifecycleStatus()).isEqualTo(LifecycleStatus.DRAFT);SkillVersionEntity withdrawn=new SkillVersionEntity(skill,null,ChangeType.INITIAL,user);ReflectionTestUtils.setField(withdrawn,"id",10L);withdrawn.submit("1.0.0",user);withdrawn.approve(user);when(skillService.version(10L)).thenReturn(withdrawn);service.withdraw(10L,0,"change",1L,"r");assertThat(withdrawn.getLifecycleStatus()).isEqualTo(LifecycleStatus.DRAFT);ArtifactBuildTaskEntity task=new ArtifactBuildTaskEntity(version,"same",user,Instant.EPOCH);when(tasks.findByIdempotencyKey("same")).thenReturn(Optional.of(task));assertThat(service.publish(3L,"same",1L,"r").idempotencyKey()).isEqualTo("same");}
 @Test void blocksSubmitWhenDependencyResolutionHasConflicts(){when(resolver.resolve(3L)).thenReturn(new DependencyService.ResolveView(List.of(),List.of("cycle")));assertThatThrownBy(()->service.submit(3L,0,"review",1L,"r")).hasMessageContaining("Dependency validation failed");}
 @Test void rejectsPublishingVersionThatIsNotApproved(){assertThatThrownBy(()->service.publish(3L,"new-key",1L,"r")).hasMessageContaining("VERSION_NOT_APPROVED");verifyNoInteractions(publication);}
 @Test void rejectsConcurrentBuildTask(){version.submit("1.0.0",user);version.approve(user);when(tasks.existsByVersionIdAndStatusIn(3L,List.of("PENDING","RUNNING"))).thenReturn(true);assertThatThrownBy(()->service.publish(3L,"parallel",1L,"r")).hasMessageContaining("BUILD_TASK_ALREADY_RUNNING");}
 @Test void pagesAndFiltersReviewHistoryAndWiresNotifications(){service.setNotifications(mock(com.company.skillplatform.notification.application.NotificationService.class));when(reviews.findAll(any(org.springframework.data.jpa.domain.Specification.class),any(org.springframework.data.domain.Pageable.class))).thenReturn(org.springframework.data.domain.Page.empty());assertThat(service.reviews(ReviewStatus.REJECTED,"root",org.springframework.data.domain.Pageable.unpaged())).isEmpty();}
 @Test void productionConstructorAndCompatibilitySetterAreWired(){WorkflowService wired=new WorkflowService(reviews,histories,tasks,skills,dependencies,skillService,resolver,new SemanticVersionPolicy(),users,publication,audit);wired.setCompatibility(mock(com.company.skillplatform.compatibility.application.CompatibilityService.class));assertThat(wired).isNotNull();}
 @BeforeEach void buildTaskClaimSetup(){when(tasks.saveAndFlush(any())).thenAnswer(i->{ArtifactBuildTaskEntity t=i.getArgument(0);ReflectionTestUtils.setField(t,"id",5L);taskRef.set(t);return t;});when(tasks.claim(anyLong(),any())).thenReturn(1);}
}
